package nl.timtoys.corruptedadventure.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.feature.ConfiguredFeature;
import nl.timtoys.corruptedadventure.CorruptedAdventure;

/**
 * Keys of the mod's configured features. The features themselves are datapack entries, generated by datagen.
 */
public final class ModConfiguredFeatures {
    // Withered expanse (transition 1→2). The dead trees are bare trunks, usable anywhere on #dirt.
    public static final ResourceKey<ConfiguredFeature<?, ?>> DEAD_TREE = key("dead_tree");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DEAD_TREE_FORKED = key("dead_tree_forked");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_TREES = key("withered_trees");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_VEGETATION = key("withered_vegetation");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_SANDSTONE_ROCK = key("withered_sandstone_rock");
    public static final ResourceKey<ConfiguredFeature<?, ?>> WITHERED_SAND_PATCH = key("withered_sand_patch");
    // Ring 1 horror features.
    public static final ResourceKey<ConfiguredFeature<?, ?>> BARE_PATCH = key("bare_patch");
    public static final ResourceKey<ConfiguredFeature<?, ?>> UNNATURAL_TUNNEL = key("unnatural_tunnel");
    // Nether ring 1.
    public static final ResourceKey<ConfiguredFeature<?, ?>> SOUL_CRYSTAL_ORE = key("soul_crystal_ore");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CRIMSON_SOUL_CRYSTAL_ORE = key("crimson_soul_crystal_ore");
    // Ring 2 (Ring2Features). PALM_TREE is also what the palm sapling grows (ModTreeGrowers.PALM).
    public static final ResourceKey<ConfiguredFeature<?, ?>> PALM_TREE = key("palm_tree");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_VEGETATION = key("oasis_vegetation");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CANYONLANDS_VEGETATION = key("canyonlands_vegetation");
    // Ring 2 dressing (change 23c).
    public static final ResourceKey<ConfiguredFeature<?, ?>> PALM_BUSH = key("palm_bush");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_SHORE_CANE = key("oasis_shore_cane");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_SHORE_PLANTS = key("oasis_shore_plants");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_TRANSITION_VEGETATION = key("oasis_transition_vegetation");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_ROCK = key("oasis_rock");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CANYON_BOULDER = key("canyon_boulder");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CANYON_RUBBLE = key("canyon_rubble");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CANYON_ROCKFALL = key("canyon_rockfall");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CANYON_SPRING = key("canyon_spring");
    // Ring 2 extra biomes (change 30); the hoodoo fields reuse CANYONLANDS_VEGETATION.
    public static final ResourceKey<ConfiguredFeature<?, ?>> SALT_CRYSTAL = key("salt_crystal");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DUNE_SEA_VEGETATION = key("dune_sea_vegetation");
    // Ring 2 salt and dune shapes and water (change 30b, Ring2FlatsFeatures).
    public static final ResourceKey<ConfiguredFeature<?, ?>> BRINE_POOL = key("brine_pool");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DUNE_OASIS = key("dune_oasis");
    public static final ResourceKey<ConfiguredFeature<?, ?>> SALT_PILLAR = key("salt_pillar");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DUNE_ROCK = key("dune_rock");
    public static final ResourceKey<ConfiguredFeature<?, ?>> SALT_ISLAND_ROCK = key("salt_island_rock");
    // Ring 2 vegetation, cactus groups, fossils and bones (change 30c, Ring2DressingFeatures); the oasis flowers and
    // shrubs are with the rest of the oasis (Ring2Features).
    public static final ResourceKey<ConfiguredFeature<?, ?>> DUNE_VALLEY_FLORA = key("dune_valley_flora");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DRY_GRASS = key("dry_grass");
    public static final ResourceKey<ConfiguredFeature<?, ?>> CACTUS_COLUMN = key("cactus_column");
    public static final ResourceKey<ConfiguredFeature<?, ?>> SHORT_CACTUS_COLUMN = key("short_cactus_column");
    public static final ResourceKey<ConfiguredFeature<?, ?>> PILLAR_FOOT_FLORA = key("pillar_foot_flora");
    public static final ResourceKey<ConfiguredFeature<?, ?>> SALT_ISLAND_FLORA = key("salt_island_flora");
    public static final ResourceKey<ConfiguredFeature<?, ?>> DESERT_FOSSIL = key("desert_fossil");
    public static final ResourceKey<ConfiguredFeature<?, ?>> BONE_RUBBLE = key("bone_rubble");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_FLOWERS_WARM = key("oasis_flowers_warm");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_FLOWERS_WHITE = key("oasis_flowers_white");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_FLOWERS_PURPLE = key("oasis_flowers_purple");
    public static final ResourceKey<ConfiguredFeature<?, ?>> OASIS_EDGE_SHRUBS = key("oasis_edge_shrubs");
    // Ring 2 ores (change 25); the tapered vanilla ores reuse vanilla's configured features.
    public static final ResourceKey<ConfiguredFeature<?, ?>> SUNSTONE_ORE = key("sunstone_ore");
    public static final ResourceKey<ConfiguredFeature<?, ?>> TURQUOISE_ORE = key("turquoise_ore");

    private ModConfiguredFeatures() {
    }

    private static ResourceKey<ConfiguredFeature<?, ?>> key(String path) {
        return ResourceKey.create(Registries.CONFIGURED_FEATURE, CorruptedAdventure.id(path));
    }
}
